SELECT 'Account.count' AS name, count(*)::text AS value FROM Account;
SELECT 'Account.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((username)::text, '~'), coalesce((identifier)::text, '~'), coalesce((created_at)::text, '~'), coalesce((updated_at)::text, '~'), coalesce((deleted_at)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM Account;
SELECT 'Jwk.count' AS name, count(*)::text AS value FROM Jwk;
SELECT 'Jwk.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((account_id)::text, '~'), coalesce((kid)::text, '~'), coalesce((kms_key_ref)::text, '~'), coalesce(("key")::text, '~'), coalesce((created_at)::text, '~'), coalesce((revoked_at)::text, '~'), coalesce((revoked_reason)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM Jwk;
SELECT 'Subordinate.count' AS name, count(*)::text AS value FROM Subordinate;
SELECT 'Subordinate.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((account_id)::text, '~'), coalesce((identifier)::text, '~'), coalesce((created_at)::text, '~'), coalesce((deleted_at)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM Subordinate;
SELECT 'EntityConfigurationStatement.count' AS name, count(*)::text AS value FROM EntityConfigurationStatement;
SELECT 'EntityConfigurationStatement.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((account_id)::text, '~'), coalesce((statement)::text, '~'), coalesce((expires_at)::text, '~'), coalesce((created_at)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM EntityConfigurationStatement;
SELECT 'Metadata.count' AS name, count(*)::text AS value FROM Metadata;
SELECT 'Metadata.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((account_id)::text, '~'), coalesce(("key")::text, '~'), coalesce((metadata)::text, '~'), coalesce((created_at)::text, '~'), coalesce((deleted_at)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM Metadata;
SELECT 'AuthorityHint.count' AS name, count(*)::text AS value FROM AuthorityHint;
SELECT 'AuthorityHint.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((account_id)::text, '~'), coalesce((identifier)::text, '~'), coalesce((created_at)::text, '~'), coalesce((deleted_at)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM AuthorityHint;
SELECT 'Crit.count' AS name, count(*)::text AS value FROM Crit;
SELECT 'Crit.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((account_id)::text, '~'), coalesce((claim)::text, '~'), coalesce((created_at)::text, '~'), coalesce((deleted_at)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM Crit;
SELECT 'SubordinateStatement.count' AS name, count(*)::text AS value FROM SubordinateStatement;
SELECT 'SubordinateStatement.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((subordinate_id)::text, '~'), coalesce((iss)::text, '~'), coalesce((sub)::text, '~'), coalesce((statement)::text, '~'), coalesce((expires_at)::text, '~'), coalesce((created_at)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM SubordinateStatement;
SELECT 'SubordinateJwk.count' AS name, count(*)::text AS value FROM SubordinateJwk;
SELECT 'SubordinateJwk.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((subordinate_id)::text, '~'), coalesce(("key")::text, '~'), coalesce((created_at)::text, '~'), coalesce((deleted_at)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM SubordinateJwk;
SELECT 'SubordinateMetadata.count' AS name, count(*)::text AS value FROM SubordinateMetadata;
SELECT 'SubordinateMetadata.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((account_id)::text, '~'), coalesce((subordinate_id)::text, '~'), coalesce(("key")::text, '~'), coalesce((metadata)::text, '~'), coalesce((created_at)::text, '~'), coalesce((deleted_at)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM SubordinateMetadata;
SELECT 'TrustMarkType.count' AS name, count(*)::text AS value FROM TrustMarkType;
SELECT 'TrustMarkType.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((account_id)::text, '~'), coalesce((identifier)::text, '~'), coalesce((created_at)::text, '~'), coalesce((updated_at)::text, '~'), coalesce((deleted_at)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM TrustMarkType;
SELECT 'TrustMarkIssuer.count' AS name, count(*)::text AS value FROM TrustMarkIssuer;
SELECT 'TrustMarkIssuer.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((trust_mark_type_id)::text, '~'), coalesce((issuer_identifier)::text, '~'), coalesce((created_at)::text, '~'), coalesce((deleted_at)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM TrustMarkIssuer;
SELECT 'TrustMark.count' AS name, count(*)::text AS value FROM TrustMark;
SELECT 'TrustMark.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((account_id)::text, '~'), coalesce((trust_mark_id)::text, '~'), coalesce((sub)::text, '~'), coalesce((trust_mark_value)::text, '~'), coalesce((iat)::text, '~'), coalesce((exp)::text, '~'), coalesce((created_at)::text, '~'), coalesce((deleted_at)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM TrustMark;
SELECT 'ReceivedTrustMark.count' AS name, count(*)::text AS value FROM ReceivedTrustMark;
SELECT 'ReceivedTrustMark.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((account_id)::text, '~'), coalesce((trust_mark_id)::text, '~'), coalesce((jwt)::text, '~'), coalesce((created_at)::text, '~'), coalesce((deleted_at)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM ReceivedTrustMark;
SELECT 'MetadataPolicy.count' AS name, count(*)::text AS value FROM MetadataPolicy;
SELECT 'MetadataPolicy.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((account_id)::text, '~'), coalesce(("key")::text, '~'), coalesce((policy)::text, '~'), coalesce((created_at)::text, '~'), coalesce((deleted_at)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM MetadataPolicy;
SELECT 'Log.count' AS name, count(*)::text AS value FROM Log;
SELECT 'Log.rows' AS name, md5(coalesce(string_agg(concat_ws('|', coalesce((id)::text, '~'), coalesce((severity)::text, '~'), coalesce((message)::text, '~'), coalesce((tag)::text, '~'), coalesce(("timestamp")::text, '~'), coalesce((throwable_message)::text, '~'), coalesce((throwable_stacktrace)::text, '~'), coalesce((metadata)::text, '~')), E'\n' ORDER BY id), '')) AS value FROM Log;
SELECT 'rel.jwk.owner' AS name, md5(coalesce(string_agg(a.username || '/' || coalesce(a.deleted_at::text, 'active') || '>' || j.kid || '>' || j.kms_key_ref, E'\n' ORDER BY j.id), '')) AS value FROM Jwk j JOIN Account a ON a.id = j.account_id;
SELECT 'rel.subordinate.owner' AS name, md5(coalesce(string_agg(a.username || '/' || coalesce(a.deleted_at::text, 'active') || '>' || s.identifier || '>' || coalesce(s.deleted_at::text, 'active'), E'\n' ORDER BY s.id), '')) AS value FROM Subordinate s JOIN Account a ON a.id = s.account_id;
SELECT 'rel.subordinate.statement' AS name, md5(coalesce(string_agg(s.identifier || '>' || ss.iss || '>' || ss.sub || '>' || ss.expires_at, E'\n' ORDER BY ss.id), '')) AS value FROM SubordinateStatement ss JOIN Subordinate s ON s.id = ss.subordinate_id;
SELECT 'rel.trustmark.issuer' AS name, md5(coalesce(string_agg(a.username || '>' || t.identifier || '>' || i.issuer_identifier, E'\n' ORDER BY i.id), '')) AS value FROM TrustMarkIssuer i JOIN TrustMarkType t ON t.id = i.trust_mark_type_id JOIN Account a ON a.id = t.account_id;
SELECT 'rel.entity.statement' AS name, md5(coalesce(string_agg(a.username || '>' || e.expires_at, E'\n' ORDER BY e.id), '')) AS value FROM EntityConfigurationStatement e JOIN Account a ON a.id = e.account_id;
